import {execFileSync} from 'node:child_process';
const root='/Users/obarbozaa/.codex/worktrees/6dc1/fidy-ai';
const resolvePackages={name:'repo-packages',setup(build:any){build.onResolve({filter:/^(effect|@fidy\/server\/client)(\/.*)?$/},(args:any)=>({path:Bun.resolveSync(args.path,root+'/apps/web/src/transport')}));}};
let app=await Bun.file('/tmp/fidy-core-read-profile-worker.ts').text();
app=app.replace('export default {async fetch(request:Request,bindings:any){','async function coreRead(request:Request,bindings:any){').replace(/\}\};\s*$/,'}');
app=app.replace('try{return await target.get(key)}finally',`try{if(bindings.PROBE_VARIANT==='rpc'){if(key!=='recovery/generation')throw new Error('Unexpected prototype key');const generation=await bindings.CELL.getByName('synthetic-control').read();return {size:generation.length,etag:'synthetic-only',text:()=>Promise.resolve(generation)};}return await target.get(key)}finally`);
app+=`\nexport default {async fetch(request:Request,env:any){const url=new URL(request.url),match=/^\\/(r2|rpc)\\/categories$/.exec(url.pathname);if(request.method!=='GET'||!match||url.search)return new Response(null,{status:404});url.pathname='/categories';const start=Date.now();const result=await coreRead(new Request(url,request),{...env,PROBE_VARIANT:match[1]});const headers=new Headers(result.headers);headers.set('x-probe-started-at',new Date(start).toISOString());headers.set('x-probe-finished-at',new Date().toISOString());return new Response(result.body,{status:result.status,headers});}};`;
await Bun.write('/tmp/fidy-generation-prototype-app.ts',app);
const paths=Array.from(new Bun.Glob('*.sql').scanSync({cwd:root+'/apps/server/cloudflare/migrations'})).sort();const sql=(await Promise.all(paths.map(n=>Bun.file(root+'/apps/server/cloudflare/migrations/'+n).text()))).join('\n--> statement-breakpoint\n').split('--> statement-breakpoint').map(s=>s.trim()).filter(s=>s&&!s.startsWith('PRAGMA '));
const source=`import {WorkflowEntrypoint,DurableObject} from 'cloudflare:workers';
import {Effect,Context,Layer} from 'effect';import {FetchHttpClient,HttpClient} from 'effect/http';
import {browserHttpClientLayer} from '${root}/apps/web/src/transport/browser-http-policy.ts';
export default {fetch(){return new Response(null,{status:404})}};
export class ControlCell extends DurableObject {constructor(ctx,env){super(ctx,env);ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS control (id INTEGER PRIMARY KEY,generation TEXT NOT NULL)');ctx.storage.sql.exec(\"INSERT OR IGNORE INTO control VALUES (1,'initial')\");}read(){return this.ctx.storage.sql.exec('SELECT generation FROM control WHERE id=1').one().generation;}}
const schema=${JSON.stringify(sql)},config={retries:{limit:0,delay:1},timeout:'2 minutes'};
export class GenerationProbe extends WorkflowEntrypoint {async run(event,step){if(Object.keys(event.payload).join()!=='offset'||![0,4,8].includes(event.payload.offset))throw new Error('Invalid probe');const offset=event.payload.offset;
if(offset===0)for(let i=0;i<schema.length;i+=250)await step.do('schema-'+i,config,async()=>{for(let j=i;j<Math.min(i+250,schema.length);j+=50)await this.env.DB.batch(schema.slice(j,Math.min(j+50,i+250,schema.length)).map(s=>this.env.DB.prepare(s)));return true;});
if(offset===0)await step.do('registry',config,async()=>{await this.env.ERASURE_BUCKET.put('recovery/generation','initial');await this.env.CELL.getByName('synthetic-control').read();return true;});
const results=[];for(let trial=offset;trial<offset+4;trial++)results.push(await step.do('paired-read-'+trial,config,async()=>{const mode=trial%4===0||trial%4===3?'r2':'rpc',current=Date.now(),n=trial+1,id=part=>part+'0000000-0000-4000-8000-'+String(n).padStart(12,'0'),token=String(n).padStart(43,'b'),digest=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token)));
await this.env.DB.batch([this.env.DB.prepare(\"INSERT INTO users(id,service_market,locale,time_zone,created_at_ms) VALUES (?,'CO','es-CO','America/Bogota',?)\").bind(id(1),current),this.env.DB.prepare(\"INSERT INTO browser_login_pairings(id,public_code,verifier_digest,user_id,state,created_at_ms,expires_at_ms) VALUES (?,?,?,?,'consumed',?,?)\").bind(id(2),'BCDF-'+String(n).padStart(4,'B'),digest,id(1),current,current+600000),this.env.DB.prepare('INSERT INTO web_sessions(id,pairing_id,user_id,token_digest,created_at_ms,fresh_until_ms,idle_expires_at_ms,hard_expires_at_ms) VALUES (?,?,?,?,?,?,?,?)').bind(id(3),id(2),id(1),digest,current,current+600000,current+3600000,current+7776000000)]);
let attempts=0,refusals=0;const phases=[],transportFailures=[];const transport=async(input,init)=>{if(String(input)!=='https://budget-proof.invalid/categories')throw new Error('Destination refused');attempts++;const headers=new Headers(init?.headers);headers.set('Cookie','__Host-fidy_session='+token);headers.set('Fidy-Session-Binding',id(3));let response;try{response=await this.env.APP.fetch('https://budget-proof.invalid/'+mode+'/categories',{...init,headers});}catch(error){transportFailures.push({name:error?.name,message:String(error?.message??'').slice(0,256)});throw error;}if(response.status===429)refusals++;phases.push({httpCode:response.status,contentType:response.headers.get('content-type'),serverMs:Number(response.headers.get('x-fixture-total-ms')),startedAt:response.headers.get('x-probe-started-at'),finishedAt:response.headers.get('x-probe-finished-at'),phases:JSON.parse(response.headers.get('x-fixture-phases')??'[]')});return response;};
const layer=FetchHttpClient.layer.pipe(browserHttpClientLayer('canonical','https://budget-proof.invalid'));const begin=performance.now(),completions=await Effect.runPromise(Effect.gen(function*(){const context=yield*Layer.build(layer),client=Context.get(context,HttpClient.HttpClient);return yield*Effect.forEach(Array.from({length:8}),()=>Effect.gen(function*(){const response=yield*client.get('https://budget-proof.invalid/categories'),body=yield*response.json;return{httpCode:response.status,completedMs:performance.now()-begin,categories:response.status===200?body.data.length:0,errorCode:body.error?.code??null};}).pipe(Effect.catchCause(()=>Effect.succeed({httpCode:0,errorStage:'client-or-decode'}))),{concurrency:'unbounded'});}).pipe(Effect.scoped,Effect.provideService(FetchHttpClient.Fetch,transport)));return{trial,mode,elapsedMs:performance.now()-begin,attempts,refusals,transportFailures,phases,completions};}));return{scope:'Isolated performance prototype only; three fresh SQL DO reads replace three R2 reads in a synthetic Core handler. Production authority publication protocol is not implemented or claimed safe.',results};}}
`;
await Bun.write('/tmp/fidy-generation-prototype-controller.ts',source);
for(const [name,file]of [['app','/tmp/fidy-generation-prototype-app.ts'],['controller','/tmp/fidy-generation-prototype-controller.ts']]){const built=await Bun.build({entrypoints:[file],target:'browser',external:['cloudflare:workers','node:*'],tsconfig:root+'/apps/server/tsconfig.json',plugins:[resolvePackages]});if(!built.success)throw new Error(String(built.logs));await Bun.write('/tmp/fidy-generation-prototype-'+name+'.mjs',await built.outputs[0].text());console.log(name,built.outputs[0].size);}

