import importlib.util,json,pathlib,subprocess,secrets,time,uuid
s=importlib.util.spec_from_file_location('cf','/tmp/fidy-category-cf-read.py');cf=importlib.util.module_from_spec(s);s.loader.exec_module(cf)
prefix='fidy-generation-core-'+secrets.token_hex(4);app=prefix+'-api';workflow=prefix+'-probe';folder=pathlib.Path('/tmp')/prefix;folder.mkdir(mode=0o700);out=pathlib.Path('/tmp/fidy-generation-core-prototype-result.json');evidence={'prefix':prefix,'app':app,'resources':[],'namespaceId':None,'cleanup':[]}
def save():out.write_text(json.dumps(evidence,indent=2)+'\n');(folder/'resources.json').write_text(json.dumps(evidence,indent=2)+'\n')
def deploy(config,file):
 (folder/file).write_text(json.dumps(config));p=subprocess.run([cf.BUN,str(cf.ROOT/'node_modules/.bin/wrangler'),'deploy','--config',str(folder/file)],cwd=cf.ROOT,capture_output=True,text=True,timeout=90)
 if p.returncode:raise RuntimeError('Owned probe deployment failed: '+p.stderr[-1000:])
try:
 db=cf.api('accounts/'+cf.ACCOUNT+'/d1/database',{'name':prefix,'primary_location_hint':'enam'})['result'];evidence['resources'].append(('d1','d1/database/'+db['uuid']));save();cf.api('accounts/'+cf.ACCOUNT+'/r2/buckets',{'name':prefix,'locationHint':'enam'});evidence['resources'].append(('r2','r2/buckets/'+prefix));save()
 for name in ['app','controller']:(folder/(name+'.mjs')).write_bytes(pathlib.Path('/tmp/fidy-generation-prototype-'+name+'.mjs').read_bytes())
 common={'account_id':cf.ACCOUNT,'compatibility_date':'2026-09-08','compatibility_flags':['nodejs_compat'],'workers_dev':False,'preview_urls':False,'d1_databases':[{'binding':'DB','database_name':prefix,'database_id':db['uuid']}],'r2_buckets':[{'binding':'ERASURE_BUCKET','bucket_name':prefix}]}
 controller={**common,'name':prefix,'main':'controller.mjs','durable_objects':{'bindings':[{'name':'CELL','class_name':'ControlCell','script_name':prefix}]},'migrations':[{'tag':'v1','new_sqlite_classes':['ControlCell']}],'workflows':[{'binding':'PROBE','name':workflow,'class_name':'GenerationProbe'}]};evidence['resources'].extend([('controller','workers/scripts/'+prefix),('workflow','workflows/'+workflow)]);save();deploy(controller,'controller.json')
 settings=cf.api('accounts/'+cf.ACCOUNT+'/workers/scripts/'+prefix+'/settings')['result'];evidence['namespaceId']=next(b['namespace_id']for b in settings['bindings']if b['name']=='CELL');save()
 appconfig={**common,'name':app,'main':'app.mjs','durable_objects':{'bindings':[{'name':'CELL','class_name':'ControlCell','script_name':prefix}]},'observability':{'enabled':True,'head_sampling_rate':1,'logs':{'enabled':True,'invocation_logs':True}}};evidence['resources'].append(('app','workers/scripts/'+app));save();deploy(appconfig,'app.json');controller['services']=[{'binding':'APP','service':app}];deploy(controller,'controller.json')
 evidence['proof']={'scope':'Isolated synthetic complete-handler prototype; not a production authority protocol. Three separate Workflow invocations keep each controller below its Free-plan subrequest limit.','results':[]};evidence['instances']=[]
 for offset in [0,4,8]:
  identity=str(uuid.uuid4());evidence['instances'].append(identity);save();cf.api('accounts/'+cf.ACCOUNT+'/workflows/'+workflow+'/instances',{'instance_id':identity,'location_hint':'enam','params':{'offset':offset}});print('Isolated full-handler comparison offset '+str(offset)+' running',flush=True)
  deadline=time.monotonic()+180;result={}
  while time.monotonic()<deadline:
   try:result=cf.api('accounts/'+cf.ACCOUNT+'/workflows/'+workflow+'/instances/'+identity)['result']
   except RuntimeError as error:
    if 'HTTP 5' not in str(error):raise
    time.sleep(2);continue
   if result.get('status')in ['complete','errored','terminated']:break
   time.sleep(2)
  assert result.get('status')=='complete',{'status':result.get('status'),'error':result.get('error')}
  value=result['output'];block=json.loads(value)if isinstance(value,str)else value;evidence['proof']['results'].extend(block['results']);save();assert all(c['httpCode']==200 for r in block['results']for c in r['completions']),'Incomplete or failed handler reads'
 print([{k:r[k]for k in ['trial','mode','elapsedMs','attempts','refusals']}for r in evidence['proof']['results']],flush=True)

except Exception as error:evidence['failure']=str(error);save();print(str(error),flush=True)
finally:
 if evidence['namespaceId']is not None:
  try:
   controller.pop('services',None);controller['d1_databases']=[];controller['r2_buckets']=[]
   (folder/'controller.mjs').write_text("import {WorkflowEntrypoint,DurableObject} from 'cloudflare:workers';export class ControlCell extends DurableObject{read(){return 'disabled'}};export default {fetch(){return new Response(null,{status:404})}};export class GenerationProbe extends WorkflowEntrypoint{run(){return Promise.resolve({disabled:true})}}")
   deploy(controller,'controller.json');evidence['cleanup'].append({'resource':'service binding','deleted':True})
  except Exception as error:evidence['cleanup'].append({'resource':'service binding','deleted':False,'error':str(error)})
 try:cf.api('accounts/'+cf.ACCOUNT+'/workers/scripts/'+app,method='DELETE');evidence['cleanup'].append({'resource':'app','deleted':True})
 except Exception as error:evidence['cleanup'].append({'resource':'app','deleted':False,'error':str(error)})
 if evidence['namespaceId']is not None:
  try:
   controller.pop('durable_objects',None);controller['migrations'].append({'tag':'v2','deleted_classes':['ControlCell']});(folder/'controller.mjs').write_text("import {WorkflowEntrypoint} from 'cloudflare:workers';export default {fetch(){return new Response(null,{status:404})}};export class GenerationProbe extends WorkflowEntrypoint{run(){return Promise.resolve({disabled:true})}}")
   deploy(controller,'controller.json')
   try:cf.api('accounts/'+cf.ACCOUNT+'/workers/durable_objects/namespaces/'+evidence['namespaceId']+'/objects');raise RuntimeError('Owned namespace still resolves')
   except RuntimeError as error:
    if 'HTTP 404;'not in str(error):raise
   evidence['cleanup'].append({'resource':'namespace','deleted':True,'httpStatus':404})
  except Exception as error:evidence['cleanup'].append({'resource':'namespace','deleted':False,'error':str(error)})
 for resource,path in reversed(evidence['resources']):
  if resource=='app':continue
  try:
   if resource=='r2':
    try:cf.api('accounts/'+cf.ACCOUNT+'/'+path+'/objects/recovery%2Fgeneration',method='DELETE')
    except RuntimeError as error:
     if 'HTTP 404;'not in str(error):raise
   cf.api('accounts/'+cf.ACCOUNT+'/'+path,method='DELETE');evidence['cleanup'].append({'resource':resource,'deleted':True})
  except Exception as error:evidence['cleanup'].append({'resource':resource,'deleted':False,'error':str(error)})
 save();print({'cleanup':evidence['cleanup']},flush=True)
